uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float spark_chance : 0.0 .. 0.1 = 0.005;
uniform vec3 ember_tint : color = 1.0, 0.6, 0.3;
uniform vec3 spark_tint : color = 1.0, 0.9, 0.6;
state fixed ph;
state fixed sparks_per_frame;
void update() {
  ph = fract(ph + fixed(dt) * fixed(speed));
  sparks_per_frame = fixed(spark_chance) * fixed(led.count);
}
vec3 shade(Led led) {
  fixed d = fixed(led.dist);
  fixed h = fixed(led.pos.y);
  fixed r = fixed(0.08);
  fixed h0 = fixed(0.30);
  // radial phase around cylinder axis
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  // vertical position phase
  fixed v = h / h0;
  // ember colour based on height (hotter at bottom)
  fixed ember_h = fixed(1.0) - v;
  vec3 c = hsv2rgb(fract(ang + ph), ember_h, fixed(1.0));
  // occasional spark
  if (fract(hash(fixed(led.idx)) * fixed(3.7)) < sparks_per_frame) {
    // spark: bright white, short-lived
    c = hsv2rgb(fract(hash(fixed(led.idx)) * fixed(7.3)), fixed(1.0), fixed(1.0));
  }
  return c;
}

uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float spark_chance : 0.0 .. 0.1 = 0.005;
uniform vec3 ember_tint : color = 1.0, 0.6, 0.3;
uniform vec3 spark_tint : color = 1.0, 0.9, 0.6;
state fixed ph;
state fixed sparks_per_frame;
void update() {
  ph = fract(ph + fixed(dt) * fixed(speed));
  sparks_per_frame = fixed(spark_chance) * fixed(led.count);
}
vec3 shade(Led led) {
  fixed d = fixed(led.dist);
  fixed h = fixed(led.pos.y);
  fixed r = fixed(0.08);
  fixed h0 = fixed(0.30);
  // radial phase around cylinder axis
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  // vertical position phase
  fixed v = h / h0;
  // ember colour based on height (hotter at bottom)
  fixed ember_h = fixed(1.0) - v;
  // compute hue from ang + ph
  fixed hue = fract(ang + ph);
  // use hsv2rgb with all fixed args — returns a fixed vec3, must be returned directly
  vec3 c = hsv2rgb(hue, ember_h, fixed(1.0));
  // occasional spark
  if (fract(hash(fixed(led.idx)) * fixed(3.7)) < sparks_per_frame) {
    // spark: bright white
    vec3 spark = hsv2rgb(fract(hash(fixed(led.idx)) * fixed(7.3)), fixed(1.0), fixed(1.0));
    // mix with ember, prefer spark colour
    c = mix(c, spark, fixed(1.0));
  }
  return c;
}

